package com.primehr.migration;import org.junit.jupiter.api.Test;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.Set;import static org.assertj.core.api.Assertions.assertThat;
class SuccessionV49MigrationParityTest{@Test void pairedMigrationsHaveMatchingIntakeStructures()throws Exception{String p=read("db/migration/postgresql/V49__succession_cycle_candidate_intake.sql").toLowerCase(),s=read("db/migration/sqlserver/V49__succession_cycle_candidate_intake.sql").toLowerCase();Set<String>names=Set.of("succession_cycle","succession_continuity_risk_review","succession_candidate","succession_eligibility_finding","succession_candidate_evidence","ix_succ_cycle_window","ix_succ_risk_cycle","ix_succ_candidate_cycle","ix_succ_candidate_employee","ix_succ_eligibility_candidate","ix_succ_evidence_candidate");for(String m:Set.of(p,s)){assertThat(m).contains(names.toArray(String[]::new));assertThat(m).doesNotContain("readiness_score","ranking","rsp_referral","appointment_action","drop table","delete from");}}private String read(String path)throws IOException{try(var in=getClass().getClassLoader().getResourceAsStream(path)){if(in==null)throw new IOException(path);return new String(in.readAllBytes(),StandardCharsets.UTF_8);}}}
